type Snapshot = {
  readonly callee_set_size: readonly IRow[];
  readonly shared_count: readonly IRow[];
  readonly union_size: readonly IRow[];
};

function readSnapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    callee_set_size: selectRows(seam, `SELECT CASE WHEN json_valid("left") AND json_type("left") = 'object' THEN json_extract("left", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("left", '$.args')) || ')' ELSE "left" END AS "left", CASE WHEN json_valid("left_size") AND json_type("left_size") = 'object' THEN json_extract("left_size", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("left_size", '$.args')) || ')' ELSE "left_size" END AS "left_size" FROM "callee_set_size"`, relColumns.callee_set_size!),
    shared_count: selectRows(seam, `SELECT CASE WHEN json_valid("left") AND json_type("left") = 'object' THEN json_extract("left", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("left", '$.args')) || ')' ELSE "left" END AS "left", CASE WHEN json_valid("right") AND json_type("right") = 'object' THEN json_extract("right", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("right", '$.args')) || ')' ELSE "right" END AS "right", CASE WHEN json_valid("shared") AND json_type("shared") = 'object' THEN json_extract("shared", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("shared", '$.args')) || ')' ELSE "shared" END AS "shared" FROM "shared_count"`, relColumns.shared_count!),
    union_size: selectRows(seam, `SELECT CASE WHEN json_valid("left") AND json_type("left") = 'object' THEN json_extract("left", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("left", '$.args')) || ')' ELSE "left" END AS "left", CASE WHEN json_valid("right") AND json_type("right") = 'object' THEN json_extract("right", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("right", '$.args')) || ')' ELSE "right" END AS "right", CASE WHEN json_valid("col3") AND json_type("col3") = 'object' THEN json_extract("col3", '$.fn') || '(' || (SELECT group_concat(value, ',') FROM json_each("col3", '$.args')) || ')' ELSE "col3" END AS "col3" FROM "union_size"`, relColumns.union_size!),
  });
}

const ARRIVAL_STATEMENTS: Record<string, { kind: "log" | "set"; addSql: string; delSql: string | null }> = {
  callee_set_size: { kind: "set", addSql: `INSERT OR IGNORE INTO "callee_set_size" ("left", "left_size") VALUES (?, ?)`, delSql: `DELETE FROM "callee_set_size" WHERE "left" = ? AND "left_size" = ?` },
  shared_count: { kind: "set", addSql: `INSERT OR IGNORE INTO "shared_count" ("left", "right", "shared") VALUES (?, ?, ?)`, delSql: `DELETE FROM "shared_count" WHERE "left" = ? AND "right" = ? AND "shared" = ?` },
};

function arrivalStatement(arrival: IArrivalRow): SqlStatement {
  const template = ARRIVAL_STATEMENTS[arrival.rel];
  if (template === undefined) {
    throw new Error(`head_expression_evaluates_derived_column: tick received an arrival for undeclared rel '${arrival.rel}'`);
  }
  if (arrival.sign === "del") {
    if (template.kind === "log") {
      throw new Error(`head_expression_evaluates_derived_column: retract from log rel '${arrival.rel}' (engine.pl retract_from_log)`);
    }
    if (template.delSql === null) {
      throw new Error(`head_expression_evaluates_derived_column: rel '${arrival.rel}' has no delete statement`);
    }
    return { sql: template.delSql, args: bindArgs(arrival.row) };
  }
  return { sql: template.addSql, args: bindArgs(arrival.row) };
}

function applyArrivals(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<unknown> {
  const statements: SqlStatement[] = arrivals.map(arrivalStatement);
  return seam.runner.batch(seam.db, statements);
}

function recomputeLevels(seam: ISqlSeam): Observable<void> {
  const sql = `DELETE FROM "union_size";\nINSERT OR IGNORE INTO "union_size" ("left", "right", "col3") SELECT b0."left", b1."left", json_object('fn', '-', 'args', json_array(json_object('fn', '+', 'args', json_array(b0."left_size", b1."left_size")), b2."shared")) FROM "callee_set_size" b0, "callee_set_size" b1, "shared_count" b2 WHERE b2."left" = b0."left" AND b2."right" = b1."left"`;
  return seam.runner.executeMultiple(seam.db, sql);
}

function buildDeltas(before: Snapshot, after: Snapshot): ITickDeltas {
  const callee_set_size = multisetDiff(before.callee_set_size, after.callee_set_size);
  const shared_count = multisetDiff(before.shared_count, after.shared_count);
  const union_size = multisetDiff(before.union_size, after.union_size);
  return {
    rels: [
      { rel: "callee_set_size", add: callee_set_size.add, del: callee_set_size.del },
      { rel: "shared_count", add: shared_count.add, del: shared_count.del },
      { rel: "union_size", add: union_size.add, del: union_size.del },
    ],
    carryPending: false,
  };
}

function runTick(seam: ISqlSeam, arrivals: IArrivalBatch): Observable<ITickDeltas> {
  return readSnapshot(seam).pipe(
    concatMap((before) => applyArrivals(seam, arrivals).pipe(map(() => before))),
    concatMap((before) => recomputeLevels(seam).pipe(map(() => before))),
    concatMap((before) => readSnapshot(seam).pipe(map((after) => buildDeltas(before, after)))),
  );
  // head_expression_evaluates_derived_column: no edge rules -- absorb arrivals, recompute levels, diff.
}

export const program: IGenProgramWithBoot = {
  name: "head_expression_evaluates_derived_column",
  ddl,
  relColumns,
  arrivalTargets,
  boot,
  tick: runTick,
};
